const crypto = require('crypto');
const incoming = $input.first().json;
const headers = incoming.headers ?? {};
const body = incoming.body ?? {};
const secret = $env.DEXFOUNDRY_WEBHOOK_SECRET;
if (typeof secret !== 'string' || secret.length < 32) throw new Error('DexFoundry webhook secret is missing or too short');
const timestamp = String(headers['x-dexfoundry-timestamp'] ?? '');
const signature = String(headers['x-dexfoundry-signature'] ?? '');
const idempotencyHeader = String(headers['x-dexfoundry-idempotency-key'] ?? '');
const parsedTimestamp = Number(timestamp);
if (!Number.isInteger(parsedTimestamp) || parsedTimestamp <= 0) throw new Error('Invalid DexFoundry timestamp');
const nowSeconds = Math.floor(Date.now() / 1000);
if (Math.abs(nowSeconds - parsedTimestamp) > 300) throw new Error('DexFoundry timestamp outside replay window');
const rawIncoming = JSON.stringify(body);
const expected = 'v1=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + rawIncoming, 'utf8').digest('hex');
const actualBuffer = Buffer.from(signature, 'utf8');
const expectedBuffer = Buffer.from(expected, 'utf8');
if (actualBuffer.length !== expectedBuffer.length || !crypto.timingSafeEqual(actualBuffer, expectedBuffer)) throw new Error('Invalid DexFoundry webhook signature');
if (typeof body.idempotencyKey !== 'string' || idempotencyHeader !== body.idempotencyKey) throw new Error('DexFoundry idempotency header/body mismatch');
if (body.schemaVersion !== '1') throw new Error('Unsupported DexFoundry envelope schema');
if (typeof body.occurredAt !== 'string' || Number.isNaN(Date.parse(body.occurredAt))) throw new Error('Invalid DexFoundry occurredAt');
const result = {
  schemaVersion: '1',
  idempotencyKey: body.idempotencyKey,
  workflow: 'dexfoundry-n8n-proof',
  status: 'SUCCEEDED',
  completedAt: new Date(body.occurredAt).toISOString(),
  outputs: { transport: 'n8n', proofVersion: '2.39.7', topic: body.topic, eventId: body.eventId }
};
const rawBody = JSON.stringify(result);
const callbackTimestamp = String(Math.floor(Date.now() / 1000));
const callbackSignature = 'v1=' + crypto.createHmac('sha256', secret).update(callbackTimestamp + '.' + rawBody, 'utf8').digest('hex');
return [{ json: { rawBody, callbackTimestamp, callbackSignature, idempotencyKey: body.idempotencyKey } }];
